import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private DataSource ds;

    @Override
    public void init(ServletConfig config) throws ServletException {
        super.init(config);
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            ds = (DataSource) ctx.lookup("java:comp/env/jdbc/reportdb");
        } catch (Exception e) {
            throw new ServletException("Failed to initialize datasource", e);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Whitelist report types
        if (!reportType.matches("(summary|detail|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - sort column is validated client-side via dropdown
        String baseQuery = "SELECT id, employee_name, department, amount, created_at " +
                           "FROM expense_reports WHERE report_type = ? " +
                           "AND created_at BETWEEN ? AND ?";

        if (department != null && !department.isEmpty()) {
            // department comes from authenticated session attribute normally
            baseQuery += " AND department = '" + department + "'";
        }

        if (sortCol != null && !sortCol.isEmpty()) {
            // Sort column - can't use prepared statement for ORDER BY
            baseQuery += " ORDER BY " + sortCol;
        }

        log.fine("Executing report query for type=" + reportType);

        try (Connection conn = ds.getConnection();
             PreparedStatement ps = conn.prepareStatement(baseQuery)) {
            ps.setString(1, reportType);
            ps.setString(2, startDate);
            ps.setString(3, endDate);

            try (ResultSet rs = ps.executeQuery()) {
                resp.setContentType("application/json");
                PrintWriter out = resp.getWriter();
                out.print("[\n");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",\n");
                    first = false;
                    out.printf("{\"id\":%d,\"name\":\"%s\",\"dept\":\"%s\",\"amount\":%.2f}",
                        rs.getInt("id"),
                        rs.getString("employee_name").replace("\"", "\\\""),
                        rs.getString("department").replace("\"", "\\\""),
                        rs.getDouble("amount"));
                }
                out.print("\n]");
            }
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }
}
